from discount import final_price, tier_rate


def test_tier_boundaries():
    assert tier_rate(49) == 0.0
    assert tier_rate(50) == 0.05
    assert tier_rate(200) == 0.10
    assert tier_rate(500) == 0.20


def test_no_loyalty():
    assert final_price(100) == 95.00
    assert final_price(300) == 270.00


def test_loyalty_is_one_percent_per_year():
    assert final_price(100, loyalty_years=3) == 92.00


def test_loyalty_caps_at_five_years():
    assert final_price(100, loyalty_years=40) == 90.00


def test_combined_discount_never_exceeds_25_percent():
    assert final_price(1000, loyalty_years=5) == 750.00

